final_template:
AWSTemplateFormatVersion: '2010-09-09'
Description: IoT Core device onboarding policy with Lambda-backed custom resource

Parameters:
  Environment:
    Type: String
    Default: dev
    AllowedValues:
      - dev
      - staging
      - prod
    Description: Environment name used for tagging resources.

Resources:
  IoTDevicePolicy:
    Type: AWS::IoT::Policy
    Properties:
      PolicyName: !Sub '${AWS::StackName}-device-onboarding-policy'
      PolicyDocument:
        Version: '2012-10-17'
        Statement:
          - Effect: Allow
            Action:
              - iot:Connect
            Resource:
              - !Sub 'arn:${AWS::Partition}:iot:${AWS::Region}:${AWS::AccountId}:client/${!iot:Connection.Thing.ThingName}'
          - Effect: Allow
            Action:
              - iot:Publish
              - iot:Receive
            Resource:
              - !Sub 'arn:${AWS::Partition}:iot:${AWS::Region}:${AWS::AccountId}:topic/${!iot:Connection.Thing.ThingName}/*'
          - Effect: Allow
            Action:
              - iot:Subscribe
            Resource:
              - !Sub 'arn:${AWS::Partition}:iot:${AWS::Region}:${AWS::AccountId}:topicfilter/${!iot:Connection.Thing.ThingName}/*'
      Tags:
        - Key: Environment
          Value: !Ref Environment

  CustomResourceLambdaRole:
    Type: AWS::IAM::Role
    Properties:
      AssumeRolePolicyDocument:
        Version: '2012-10-17'
        Statement:
          - Effect: Allow
            Principal:
              Service:
                - lambda.amazonaws.com
            Action:
              - sts:AssumeRole
      ManagedPolicyArns:
        - !Sub 'arn:${AWS::Partition}:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole'
        - !Sub 'arn:${AWS::Partition}:iam::aws:policy/AWSXRayDaemonWriteAccess'
      Policies:
        - PolicyName: iot-policy-management
          PolicyDocument:
            Version: '2012-10-17'
            Statement:
              - Effect: Allow
                Action:
                  - iot:CreatePolicy
                  - iot:GetPolicy
                  - iot:AttachPolicy
                  - iot:ListPolicies
                  - iot:ListTargetsForPolicy
                  - iot:DetachPolicy
                  - iot:DeletePolicy
                Resource:
                  - !Sub 'arn:${AWS::Partition}:iot:${AWS::Region}:${AWS::AccountId}:policy/*'
      Tags:
        - Key: Environment
          Value: !Ref Environment

  CustomResourceLambda:
    Type: AWS::Lambda::Function
    Properties:
      FunctionName: !Sub '${AWS::StackName}-iot-policy-custom-resource'
      Runtime: nodejs22.x
      Handler: index.handler
      Timeout: 60
      MemorySize: 256
      TracingConfig:
        Mode: Active
      Role: !GetAtt CustomResourceLambdaRole.Arn
      Environment:
        Variables:
          IOT_POLICY_NAME: !Ref IoTDevicePolicy
      Code:
        ZipFile: |
          const { IoTClient, CreatePolicyCommand, GetPolicyCommand, DeletePolicyCommand, ListTargetsForPolicyCommand, DetachPolicyCommand } = require('@aws-sdk/client-iot');
          const https = require('https');
          const url = require('url');

          const iot = new IoTClient({});

          function sendResponse(event, context, status, data, physicalId, reason) {
            const body = JSON.stringify({
              Status: status,
              Reason: reason || `See CloudWatch log stream: ${context.logStreamName}`,
              PhysicalResourceId: physicalId || context.logStreamName,
              StackId: event.StackId,
              RequestId: event.RequestId,
              LogicalResourceId: event.LogicalResourceId,
              Data: data || {}
            });
            const parsed = url.parse(event.ResponseURL);
            const options = {
              hostname: parsed.hostname,
              port: 443,
              path: parsed.path,
              method: 'PUT',
              headers: {
                'content-type': '',
                'content-length': body.length
              }
            };
            return new Promise((resolve, reject) => {
              const req = https.request(options, (res) => {
                res.on('data', () => {});
                res.on('end', () => resolve());
              });
              req.on('error', reject);
              req.write(body);
              req.end();
            });
          }

          exports.handler = async (event, context) => {
            console.log('Received event:', JSON.stringify(event, null, 2));
            const policyName = event.ResourceProperties.PolicyName;
            const policyDocument = event.ResourceProperties.PolicyDocument;

            try {
              if (event.RequestType === 'Create' || event.RequestType === 'Update') {
                const docString = typeof policyDocument === 'string' ? policyDocument : JSON.stringify(policyDocument);
                try {
                  await iot.send(new CreatePolicyCommand({
                    policyName: policyName,
                    policyDocument: docString
                  }));
                } catch (err) {
                  if (err.name === 'ResourceAlreadyExistsException') {
                    const existing = await iot.send(new GetPolicyCommand({ policyName }));
                    const targets = await iot.send(new ListTargetsForPolicyCommand({ policyName }));
                    if (targets.targets && targets.targets.length > 0) {
                      for (const target of targets.targets) {
                        await iot.send(new DetachPolicyCommand({ policyName, target }));
                      }
                    }
                    await iot.send(new DeletePolicyCommand({ policyName }));
                    await iot.send(new CreatePolicyCommand({
                      policyName: policyName,
                      policyDocument: docString
                    }));
                  } else {
                    throw err;
                  }
                }
                await sendResponse(event, context, 'SUCCESS', { PolicyName: policyName }, policyName);
              } else if (event.RequestType === 'Delete') {
                try {
                  const targets = await iot.send(new ListTargetsForPolicyCommand({ policyName }));
                  if (targets.targets && targets.targets.length > 0) {
                    for (const target of targets.targets) {
                      await iot.send(new DetachPolicyCommand({ policyName, target }));
                    }
                  }
                  await iot.send(new DeletePolicyCommand({ policyName }));
                } catch (err) {
                  if (err.name !== 'ResourceNotFoundException') {
                    throw err;
                  }
                }
                await sendResponse(event, context, 'SUCCESS', { PolicyName: policyName }, policyName);
              }
            } catch (err) {
              console.error('Error:', err);
              await sendResponse(event, context, 'FAILED', {}, event.PhysicalResourceId || policyName, err.message);
            }
          };

  IoTDevicePolicyCustomResource:
    Type: AWS::CloudFormation::CustomResource
    Properties:
      ServiceToken: !GetAtt CustomResourceLambda.Arn
      PolicyName: !Ref IoTDevicePolicy
      PolicyDocument:
        Version: '2012-10-17'
        Statement:
          - Effect: Allow
            Action:
              - iot:Connect
            Resource:
              - !Sub 'arn:${AWS::Partition}:iot:${AWS::Region}:${AWS::AccountId}:client/${!iot:Connection.Thing.ThingName}'
          - Effect: Allow
            Action:
              - iot:Publish
              - iot:Receive
            Resource:
              - !Sub 'arn:${AWS::Partition}:iot:${AWS::Region}:${AWS::AccountId}:topic/${!iot:Connection.Thing.ThingName}/*'
          - Effect: Allow
            Action:
              - iot:Subscribe
            Resource:
              - !Sub 'arn:${AWS::Partition}:iot:${AWS::Region}:${AWS::AccountId}:topicfilter/${!iot:Connection.Thing.ThingName}/*'

Outputs:
  IoTDevicePolicyName:
    Description: Name of the generated IoT Core device onboarding policy
    Value: !GetAtt IoTDevicePolicyCustomResource.PolicyName
    Export:
      Name: !Sub '${AWS::StackName}-IoTDevicePolicyName'

  IoTDevicePolicyArn:
    Description: ARN of the IoT Core device onboarding policy
    Value: !Ref IoTDevicePolicy
    Export:
      Name: !Sub '${AWS::StackName}-IoTDevicePolicyArn'

AWSTemplateFormatVersion: '2010-09-09'
Description: Scheduled workflow to close AWS Organizations accounts tagged organizations:account-closure=REQUESTED

Resources:
  AccountClosureLogKey:
    Type: AWS::KMS::Key
    Properties:
      Description: CMK for encrypting account closure workflow CloudWatch logs
      EnableKeyRotation: true
      KeyPolicy:
        Version: '2012-10-17'
        Statement:
          - Sid: EnableRootAdministration
            Effect: Allow
            Principal:
              AWS: !Sub 'arn:${AWS::Partition}:iam::${AWS::AccountId}:root'
            Action: 'kms:*'
            Resource: '*'
          - Sid: AllowCloudWatchLogs
            Effect: Allow
            Principal:
              Service: !Sub 'logs.${AWS::Region}.amazonaws.com'
            Action:
              - kms:Encrypt
              - kms:Decrypt
              - kms:ReEncrypt*
              - kms:GenerateDataKey*
              - kms:Describe*
            Resource: '*'
            Condition:
              ArnLike:
                'kms:EncryptionContext:aws:logs:arn': !Sub 'arn:${AWS::Partition}:logs:${AWS::Region}:${AWS::AccountId}:log-group:/aws/vendedlogs/states/account-closure-workflow-${AWS::Region}'

  AccountClosureLogKeyAlias:
    Type: AWS::KMS::Alias
    Properties:
      AliasName: !Sub 'alias/account-closure-workflow-logs-${AWS::Region}'
      TargetKeyId: !Ref AccountClosureLogKey

  AccountClosureLogGroup:
    Type: AWS::Logs::LogGroup
    Properties:
      RetentionInDays: 365
      LogGroupName: !Sub '/aws/vendedlogs/states/account-closure-workflow-${AWS::Region}'
      KmsKeyId: !GetAtt AccountClosureLogKey.Arn

  AccountClosureStateMachineRole:
    Type: AWS::IAM::Role
    Properties:
      AssumeRolePolicyDocument:
        Version: '2012-10-17'
        Statement:
          - Effect: Allow
            Principal:
              Service: states.amazonaws.com
            Action: sts:AssumeRole
      Policies:
        - PolicyName: OrganizationsAccountClosurePolicy
          PolicyDocument:
            Version: '2012-10-17'
            Statement:
              - Sid: OrganizationsReadAndClose
                Effect: Allow
                Action:
                  - organizations:ListAccounts
                  - organizations:DescribeAccount
                  - organizations:ListTagsForResource
                  - organizations:TagResource
                  - organizations:CloseAccount
                Resource: '*'
              - Sid: CloudWatchLogsDelivery
                Effect: Allow
                Action:
                  - logs:CreateLogDelivery
                  - logs:GetLogDelivery
                  - logs:UpdateLogDelivery
                  - logs:DeleteLogDelivery
                  - logs:ListLogDeliveries
                  - logs:PutResourcePolicy
                  - logs:DescribeResourcePolicies
                  - logs:DescribeLogGroups
                Resource: '*'
              - Sid: LogKeyUsage
                Effect: Allow
                Action:
                  - kms:GenerateDataKey
                  - kms:GenerateDataKeyWithoutPlaintext
                  - kms:Decrypt
                Resource: !GetAtt AccountClosureLogKey.Arn

  AccountClosureStateMachine:
    Type: AWS::StepFunctions::StateMachine
    Properties:
      StateMachineName: account-closure-workflow
      StateMachineType: EXPRESS
      RoleArn: !GetAtt AccountClosureStateMachineRole.Arn
      LoggingConfiguration:
        Level: ALL
        IncludeExecutionData: true
        Destinations:
          - CloudWatchLogsLogGroup:
              LogGroupArn: !GetAtt AccountClosureLogGroup.Arn
      DefinitionString: !Sub
        - |
          {
            "Comment": "Close AWS Organizations accounts tagged organizations:account-closure=REQUESTED",
            "StartAt": "Init",
            "States": {
              "Init": {
                "Type": "Pass",
                "Result": {
                  "NextToken": null
                },
                "ResultPath": "$.context",
                "Next": "ListAccounts"
              },
              "ListAccounts": {
                "Type": "Task",
                "Resource": "arn:aws:states:::aws-sdk:organizations:listAccounts",
                "Parameters": {
                  "NextToken.$": "$.context.NextToken"
                },
                "ResultPath": "$.listResult",
                "Retry": [
                  {
                    "ErrorEquals": [
                      "Organizations.ThrottlingException",
                      "Organizations.TooManyRequestsException",
                      "Organizations.ConcurrentModificationException",
                      "Organizations.AWSOrganizationsNotInUseException",
                      "Organizations.AccountNotFoundException",
                      "Organizations.ServiceException"
                    ],
                    "IntervalSeconds": 2,
                    "MaxAttempts": 6,
                    "BackoffRate": 2.0
                  }
                ],
                "Catch": [
                  {
                    "ErrorEquals": ["States.ALL"],
                    "ResultPath": "$.error",
                    "Next": "RecordFailure"
                  }
                ],
                "Next": "ProcessAccounts"
              },
              "ProcessAccounts": {
                "Type": "Map",
                "ItemsPath": "$.listResult.Accounts",
                "ItemProcessor": {
                  "ProcessorConfig": {
                    "Mode": "INLINE"
                  },
                  "StartAt": "DescribeAccount",
                  "States": {
                    "DescribeAccount": {
                      "Type": "Task",
                      "Resource": "arn:aws:states:::aws-sdk:organizations:describeAccount",
                      "Parameters": {
                        "AccountId.$": "$.Id"
                      },
                      "ResultPath": "$.describeResult",
                      "Retry": [
                        {
                          "ErrorEquals": [
                            "Organizations.ThrottlingException",
                            "Organizations.TooManyRequestsException",
                            "Organizations.ConcurrentModificationException",
                            "Organizations.AWSOrganizationsNotInUseException",
                            "Organizations.AccountNotFoundException",
                            "Organizations.ServiceException"
                          ],
                          "IntervalSeconds": 2,
                          "MaxAttempts": 6,
                          "BackoffRate": 2.0
                        }
                      ],
                      "Catch": [
                        {
                          "ErrorEquals": ["States.ALL"],
                          "ResultPath": "$.error",
                          "Next": "MarkFailed"
                        }
                      ],
                      "Next": "ListTags"
                    },
                    "ListTags": {
                      "Type": "Task",
                      "Resource": "arn:aws:states:::aws-sdk:organizations:listTagsForResource",
                      "Parameters": {
                        "ResourceId.$": "$.Id"
                      },
                      "ResultPath": "$.tagsResult",
                      "Retry": [
                        {
                          "ErrorEquals": [
                            "Organizations.ThrottlingException",
                            "Organizations.TooManyRequestsException",
                            "Organizations.ConcurrentModificationException",
                            "Organizations.AWSOrganizationsNotInUseException",
                            "Organizations.AccountNotFoundException",
                            "Organizations.ServiceException"
                          ],
                          "IntervalSeconds": 2,
                          "MaxAttempts": 6,
                          "BackoffRate": 2.0
                        }
                      ],
                      "Catch": [
                        {
                          "ErrorEquals": ["States.ALL"],
                          "ResultPath": "$.error",
                          "Next": "MarkFailed"
                        }
                      ],
                      "Next": "FindClosureTag"
                    },
                    "FindClosureTag": {
                      "Type": "Map",
                      "ItemsPath": "$.tagsResult.Tags",
                      "ItemProcessor": {
                        "ProcessorConfig": {
                          "Mode": "INLINE"
                        },
                        "StartAt": "CheckTagKey",
                        "States": {
                          "CheckTagKey": {
                            "Type": "Choice",
                            "Choices": [
                              {
                                "Variable": "$.Key",
                                "StringEquals": "organizations:account-closure",
                                "Next": "CaptureTagValue"
                              }
                            ],
                            "Default": "NoMatch"
                          },
                          "CaptureTagValue": {
                            "Type": "Pass",
                            "Parameters": {
                              "closureTagValue.$": "$.Value"
                            },
                            "End": true
                          },
                          "NoMatch": {
                            "Type": "Pass",
                            "Parameters": {
                              "closureTagValue": null
                            },
                            "End": true
                          }
                        }
                      },
                      "ResultPath": "$.tagMatches",
                      "Next": "CheckClosureTag"
                    },
                    "CheckClosureTag": {
                      "Type": "Choice",
                      "Choices": [
                        {
                          "Variable": "$.tagMatches[0].closureTagValue",
                          "IsPresent": true,
                          "Next": "CheckTagValue"
                        }
                      ],
                      "Default": "SkipNotTagged"
                    },
                    "CheckTagValue": {
                      "Type": "Choice",
                      "Choices": [
                        {
                          "Variable": "$.tagMatches[0].closureTagValue",
                          "StringEquals": "REQUESTED",
                          "Next": "CheckStatus"
                        }
                      ],
                      "Default": "SkipNotTagged"
                    },
                    "CheckStatus": {
                      "Type": "Choice",
                      "Choices": [
                        {
                          "Variable": "$.describeResult.Account.Status",
                          "StringEquals": "ACTIVE",
                          "Next": "CloseAccount"
                        }
                      ],
                      "Default": "SkipNotActive"
                    },
                    "CloseAccount": {
                      "Type": "Task",
                      "Resource": "arn:aws:states:::aws-sdk:organizations:closeAccount",
                      "Parameters": {
                        "AccountId.$": "$.Id"
                      },
                      "ResultPath": "$.closeResult",
                      "Retry": [
                        {
                          "ErrorEquals": [
                            "Organizations.ThrottlingException",
                            "Organizations.TooManyRequestsException",
                            "Organizations.ConcurrentModificationException",
                            "Organizations.AWSOrganizationsNotInUseException",
                            "Organizations.AccountNotFoundException",
                            "Organizations.ServiceException"
                          ],
                          "IntervalSeconds": 2,
                          "MaxAttempts": 6,
                          "BackoffRate": 2.0
                        }
                      ],
                      "Catch": [
                        {
                          "ErrorEquals": ["States.ALL"],
                          "ResultPath": "$.error",
                          "Next": "MarkFailed"
                        }
                      ],
                      "Next": "TagAcknowledged"
                    },
                    "TagAcknowledged": {
                      "Type": "Task",
                      "Resource": "arn:aws:states:::aws-sdk:organizations:tagResource",
                      "Parameters": {
                        "ResourceId.$": "$.Id",
                        "Tags": [
                          {
                            "Key": "organizations:account-closure",
                            "Value": "ACKNOWLEDGED"
                          }
                        ]
                      },
                      "ResultPath": "$.tagResult",
                      "Retry": [
                        {
                          "ErrorEquals": [
                            "Organizations.ThrottlingException",
                            "Organizations.TooManyRequestsException",
                            "Organizations.ConcurrentModificationException",
                            "Organizations.AWSOrganizationsNotInUseException",
                            "Organizations.AccountNotFoundException",
                            "Organizations.ServiceException"
                          ],
                          "IntervalSeconds": 2,
                          "MaxAttempts": 6,
                          "BackoffRate": 2.0
                        }
                      ],
                      "Catch": [
                        {
                          "ErrorEquals": ["States.ALL"],
                          "ResultPath": "$.error",
                          "Next": "MarkFailed"
                        }
                      ],
                      "Next": "MarkClosed"
                    },
                    "MarkClosed": {
                      "Type": "Pass",
                      "Result": {
                        "status": "CLOSED"
                      },
                      "ResultPath": "$.outcome",
                      "End": true
                    },
                    "SkipNotTagged": {
                      "Type": "Pass",
                      "Result": {
                        "status": "SKIPPED_NOT_TAGGED"
                      },
                      "ResultPath": "$.outcome",
                      "End": true
                    },
                    "SkipNotActive": {
                      "Type": "Pass",
                      "Result": {
                        "status": "SKIPPED_NOT_ACTIVE"
                      },
                      "ResultPath": "$.outcome",
                      "End": true
                    },
                    "MarkFailed": {
                      "Type": "Pass",
                      "Parameters": {
                        "status": "FAILED",
                        "error.$": "$.error"
                      },
                      "End": true
                    }
                  }
                },
                "ResultPath": "$.processed",
                "Catch": [
                  {
                    "ErrorEquals": ["States.ALL"],
                    "ResultPath": "$.error",
                    "Next": "RecordFailure"
                  }
                ],
                "Next": "CheckNextTokenPresent"
              },
              "CheckNextTokenPresent": {
                "Type": "Choice",
                "Choices": [
                  {
                    "Variable": "$.listResult.NextToken",
                    "IsPresent": true,
                    "Next": "CheckNextTokenNotNull"
                  }
                ],
                "Default": "Succeed"
              },
              "CheckNextTokenNotNull": {
                "Type": "Choice",
                "Choices": [
                  {
                    "Variable": "$.listResult.NextToken",
                    "IsNull": false,
                    "Next": "PrepareNextPage"
                  }
                ],
                "Default": "Succeed"
              },
              "PrepareNextPage": {
                "Type": "Pass",
                "Parameters": {
                  "NextToken.$": "$.listResult.NextToken"
                },
                "ResultPath": "$.context",
                "Next": "ListAccounts"
              },
              "RecordFailure": {
                "Type": "Fail",
                "Error": "AccountClosureWorkflowFailed",
                "Cause": "The account closure workflow encountered a terminal error. See execution data in CloudWatch Logs."
              },
              "Succeed": {
                "Type": "Succeed"
              }
            }
          }
        - {}

  AccountClosureScheduleRole:
    Type: AWS::IAM::Role
    Properties:
      AssumeRolePolicyDocument:
        Version: '2012-10-17'
        Statement:
          - Effect: Allow
            Principal:
              Service: events.amazonaws.com
            Action: sts:AssumeRole
      Policies:
        - PolicyName: StartAccountClosureExecution
          PolicyDocument:
            Version: '2012-10-17'
            Statement:
              - Effect: Allow
                Action: states:StartExecution
                Resource: !Ref AccountClosureStateMachine

  AccountClosureScheduleRule:
    Type: AWS::Events::Rule
    Properties:
      Name: account-closure-hourly-schedule
      Description: Triggers the account closure workflow every hour
      ScheduleExpression: rate(1 hour)
      State: ENABLED
      Targets:
        - Id: AccountClosureStateMachineTarget
          Arn: !Ref AccountClosureStateMachine
          RoleArn: !GetAtt AccountClosureScheduleRole.Arn

Outputs:
  StateMachineArn:
    Description: ARN of the account closure state machine
    Value: !Ref AccountClosureStateMachine
  EventBridgeRuleName:
    Description: Name of the EventBridge schedule rule
    Value: !Ref AccountClosureScheduleRule
  LogGroupName:
    Description: Name of the CloudWatch log group for state machine execution logs
    Value: !Ref AccountClosureLogGroup
  LogKeyArn:
    Description: ARN of the KMS key used to encrypt the workflow log group
    Value: !GetAtt AccountClosureLogKey.Arn

AWSTemplateFormatVersion: '2010-09-09'
Description: Amazon Verified Permissions policy store for a bookstore application with Cedar schema and static policies.

Resources:
  PolicyStore:
    Type: AWS::VerifiedPermissions::PolicyStore
    Properties:
      ValidationSettings:
        Mode: STRICT
      Schema:
        CedarJson: |
          {
            "Bookstore": {
              "entityTypes": {
                "Role": {
                  "shape": {
                    "type": "Record",
                    "attributes": {}
                  }
                },
                "User": {
                  "shape": {
                    "type": "Record",
                    "attributes": {
                      "yearsAsMember": {
                        "type": "Long"
                      }
                    }
                  },
                  "memberOfTypes": [
                    "Role"
                  ]
                },
                "Book": {
                  "shape": {
                    "type": "Record",
                    "attributes": {
                      "owner": {
                        "type": "Entity",
                        "name": "User"
                      }
                    }
                  }
                }
              },
              "actions": {
                "View": {
                  "appliesTo": {
                    "principalTypes": [
                      "User"
                    ],
                    "resourceTypes": [
                      "Book"
                    ],
                    "context": {
                      "type": "Record",
                      "attributes": {
                        "region": {
                          "type": "String"
                        }
                      }
                    }
                  }
                },
                "ViewWithPremiumOffers": {
                  "appliesTo": {
                    "principalTypes": [
                      "User"
                    ],
                    "resourceTypes": [
                      "Book"
                    ],
                    "context": {
                      "type": "Record",
                      "attributes": {
                        "region": {
                          "type": "String"
                        }
                      }
                    }
                  }
                }
              }
            }
          }

  AdminViewPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !GetAtt PolicyStore.PolicyStoreId
      Definition:
        Static:
          Description: Permit users in the Admin role to view any book.
          Statement: |
            permit(
              principal in Bookstore::Role::"Admin",
              action == Bookstore::Action::"View",
              resource
            );

  ForbidSpecificAdminViewPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !GetAtt PolicyStore.PolicyStoreId
      Definition:
        Static:
          Description: Forbid the specific named administrator from viewing any book.
          Statement: |
            forbid(
              principal == Bookstore::User::"blockedAdmin",
              action == Bookstore::Action::"View",
              resource
            );

  PublisherViewOwnedPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !GetAtt PolicyStore.PolicyStoreId
      Definition:
        Static:
          Description: Permit users in the Publisher role to view only books they own.
          Statement: |
            permit(
              principal in Bookstore::Role::"Publisher",
              action == Bookstore::Action::"View",
              resource
            )
            when {
              resource.owner == principal
            };

  SpecificUserViewSpecificBookPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !GetAtt PolicyStore.PolicyStoreId
      Definition:
        Static:
          Description: Permit a specific named user to view a specific named book.
          Statement: |
            permit(
              principal == Bookstore::User::"alice",
              action == Bookstore::Action::"View",
              resource == Bookstore::Book::"theGreatGatsby"
            );

  CustomerPremiumOffersPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !GetAtt PolicyStore.PolicyStoreId
      Definition:
        Static:
          Description: Permit customers to view premium offers when in the United States and a member for at least two years.
          Statement: |
            permit(
              principal in Bookstore::Role::"Customer",
              action == Bookstore::Action::"ViewWithPremiumOffers",
              resource
            )
            when {
              context.region == "United States" &&
              principal.yearsAsMember >= 2
            };

  ForbidNewCustomerPremiumOffersPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !GetAtt PolicyStore.PolicyStoreId
      Definition:
        Static:
          Description: Forbid customers with less than two years of membership from viewing premium offers.
          Statement: |
            forbid(
              principal in Bookstore::Role::"Customer",
              action == Bookstore::Action::"ViewWithPremiumOffers",
              resource
            )
            when {
              principal.yearsAsMember < 2
            };

  ForbidNonUSRegionPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !GetAtt PolicyStore.PolicyStoreId
      Definition:
        Static:
          Description: Forbid View and ViewWithPremiumOffers when the request region is not the United States.
          Statement: |
            forbid(
              principal,
              action in [
                Bookstore::Action::"View",
                Bookstore::Action::"ViewWithPremiumOffers"
              ],
              resource
            )
            when {
              context.region != "United States"
            };

  PolicyStoreIdParameter:
    Type: AWS::SSM::Parameter
    Properties:
      Name: /bookstore/verified-permissions/policy-store-id
      Type: String
      Value: !GetAtt PolicyStore.PolicyStoreId
      Description: Amazon Verified Permissions policy store ID for the bookstore application.

Outputs:
  PolicyStoreId:
    Description: The ID of the Amazon Verified Permissions policy store.
    Value: !GetAtt PolicyStore.PolicyStoreId

  PolicyStoreArn:
    Description: The ARN of the Amazon Verified Permissions policy store.
    Value: !GetAtt PolicyStore.Arn

  PolicyStoreIdParameterName:
    Description: The SSM Parameter name holding the policy store ID.
    Value: !Ref PolicyStoreIdParameter

AWSTemplateFormatVersion: '2010-09-09'
Description: SimpleTodoAPI - AppSync GraphQL API with JavaScript resolvers backed by DynamoDB

Resources:
  TodoTableKey:
    Type: AWS::KMS::Key
    Properties:
      Description: Customer-managed KMS key for the SimpleTodoAPI DynamoDB table
      EnableKeyRotation: true
      KeyPolicy:
        Version: '2012-10-17'
        Statement:
          - Sid: EnableRootAccountAccess
            Effect: Allow
            Principal:
              AWS: !Sub 'arn:${AWS::Partition}:iam::${AWS::AccountId}:root'
            Action: 'kms:*'
            Resource: '*'

  TodoTable:
    Type: AWS::DynamoDB::Table
    DeletionPolicy: Retain
    UpdateReplacePolicy: Retain
    Properties:
      BillingMode: PAY_PER_REQUEST
      PointInTimeRecoverySpecification:
        PointInTimeRecoveryEnabled: true
      SSESpecification:
        SSEEnabled: true
        SSEType: KMS
        KMSMasterKeyId: !GetAtt TodoTableKey.Arn
      AttributeDefinitions:
        - AttributeName: id
          AttributeType: S
        - AttributeName: owner
          AttributeType: S
      KeySchema:
        - AttributeName: id
          KeyType: HASH
      GlobalSecondaryIndexes:
        - IndexName: owner-index
          KeySchema:
            - AttributeName: owner
              KeyType: HASH
            - AttributeName: id
              KeyType: RANGE
          Projection:
            ProjectionType: ALL

  AppSyncServiceRole:
    Type: AWS::IAM::Role
    Properties:
      AssumeRolePolicyDocument:
        Version: '2012-10-17'
        Statement:
          - Effect: Allow
            Principal:
              Service: appsync.amazonaws.com
            Action: sts:AssumeRole
      Policies:
        - PolicyName: AppSyncTodoTableAccess
          PolicyDocument:
            Version: '2012-10-17'
            Statement:
              - Effect: Allow
                Action:
                  - dynamodb:GetItem
                  - dynamodb:PutItem
                  - dynamodb:UpdateItem
                  - dynamodb:DeleteItem
                  - dynamodb:Query
                  - dynamodb:Scan
                Resource:
                  - !GetAtt TodoTable.Arn
                  - !Sub '${TodoTable.Arn}/index/owner-index'
              - Effect: Allow
                Action:
                  - kms:Decrypt
                  - kms:GenerateDataKey
                  - kms:GenerateDataKeyWithoutPlaintext
                Resource:
                  - !GetAtt TodoTableKey.Arn

  GraphQLApi:
    Type: AWS::AppSync::GraphQLApi
    Properties:
      Name: SimpleTodoAPI
      AuthenticationType: API_KEY
      XrayEnabled: true

  GraphQLApiKey:
    Type: AWS::AppSync::ApiKey
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      Description: API key for SimpleTodoAPI testing
      Expires: 1798761600

  GraphQLSchema:
    Type: AWS::AppSync::GraphQLSchema
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      Definition: |
        type Todo {
          id: ID!
          owner: String
          title: String
          description: String
          status: String
          createdAt: String
          updatedAt: String
        }

        type Query {
          getTodo(id: ID!): Todo
          listTodos: [Todo]
          todosByOwner(owner: String!): [Todo]
        }

        type Mutation {
          createTodo(input: CreateTodoInput!): Todo
          updateTodo(input: UpdateTodoInput!): Todo
          deleteTodo(input: DeleteTodoInput!): Todo
        }

        input CreateTodoInput {
          id: ID
          owner: String
          title: String
          description: String
          status: String
        }

        input UpdateTodoInput {
          id: ID!
          owner: String
          title: String
          description: String
          status: String
        }

        input DeleteTodoInput {
          id: ID!
        }

        schema {
          query: Query
          mutation: Mutation
        }

  TodoDataSource:
    Type: AWS::AppSync::DataSource
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      Name: TodoTableDataSource
      Type: AMAZON_DYNAMODB
      ServiceRoleArn: !GetAtt AppSyncServiceRole.Arn
      DynamoDBConfig:
        TableName: !Ref TodoTable
        AwsRegion: !Ref AWS::Region

  CreateTodoResolver:
    Type: AWS::AppSync::Resolver
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      TypeName: Mutation
      FieldName: createTodo
      DataSourceName: !GetAtt TodoDataSource.Name
      Kind: UNIT
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const input = ctx.args.input;
          const now = util.time.nowISO8601();
          const id = input.id || util.autoId();
          const item = {
            id: id,
            owner: input.owner,
            title: input.title,
            description: input.description,
            status: input.status,
            createdAt: now,
            updatedAt: now,
          };
          return {
            operation: 'PutItem',
            key: util.dynamodb.toMapValues({ id: id }),
            attributeValues: util.dynamodb.toMapValues(item),
          };
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return ctx.result;
        }

  UpdateTodoResolver:
    Type: AWS::AppSync::Resolver
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      TypeName: Mutation
      FieldName: updateTodo
      DataSourceName: !GetAtt TodoDataSource.Name
      Kind: UNIT
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const input = ctx.args.input;
          const id = input.id;
          const now = util.time.nowISO8601();

          const expressionNames = {
            '#owner': 'owner',
            '#title': 'title',
            '#description': 'description',
            '#status': 'status',
            '#updatedAt': 'updatedAt',
          };

          const values = { ':updatedAt': now };
          const sets = ['#updatedAt = :updatedAt'];

          if (input.owner !== undefined && input.owner !== null) {
            sets.push('#owner = :owner');
            values[':owner'] = input.owner;
          }
          if (input.title !== undefined && input.title !== null) {
            sets.push('#title = :title');
            values[':title'] = input.title;
          }
          if (input.description !== undefined && input.description !== null) {
            sets.push('#description = :description');
            values[':description'] = input.description;
          }
          if (input.status !== undefined && input.status !== null) {
            sets.push('#status = :status');
            values[':status'] = input.status;
          }

          return {
            operation: 'UpdateItem',
            key: util.dynamodb.toMapValues({ id: id }),
            update: {
              expression: 'SET ' + sets.join(', '),
              expressionNames: expressionNames,
              expressionValues: util.dynamodb.toMapValues(values),
            },
          };
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return ctx.result;
        }

  DeleteTodoResolver:
    Type: AWS::AppSync::Resolver
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      TypeName: Mutation
      FieldName: deleteTodo
      DataSourceName: !GetAtt TodoDataSource.Name
      Kind: UNIT
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const id = ctx.args.input.id;
          return {
            operation: 'DeleteItem',
            key: util.dynamodb.toMapValues({ id: id }),
          };
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return ctx.result;
        }

  GetTodoResolver:
    Type: AWS::AppSync::Resolver
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      TypeName: Query
      FieldName: getTodo
      DataSourceName: !GetAtt TodoDataSource.Name
      Kind: UNIT
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          return {
            operation: 'GetItem',
            key: util.dynamodb.toMapValues({ id: ctx.args.id }),
          };
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return ctx.result;
        }

  ListTodosResolver:
    Type: AWS::AppSync::Resolver
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      TypeName: Query
      FieldName: listTodos
      DataSourceName: !GetAtt TodoDataSource.Name
      Kind: UNIT
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          return {
            operation: 'Scan',
          };
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return ctx.result.items;
        }

  TodosByOwnerResolver:
    Type: AWS::AppSync::Resolver
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      TypeName: Query
      FieldName: todosByOwner
      DataSourceName: !GetAtt TodoDataSource.Name
      Kind: UNIT
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          return {
            operation: 'Query',
            query: {
              expression: '#owner = :owner',
              expressionNames: { '#owner': 'owner' },
              expressionValues: util.dynamodb.toMapValues({ ':owner': ctx.args.owner }),
            },
            index: 'owner-index',
          };
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return ctx.result.items;
        }

Outputs:
  GraphQLApiId:
    Description: The ID of the AppSync GraphQL API
    Value: !GetAtt GraphQLApi.ApiId

  GraphQLApiUrl:
    Description: The URL of the AppSync GraphQL API
    Value: !GetAtt GraphQLApi.GraphQLUrl

  GraphQLApiKeyId:
    Description: The ID of the AppSync API key
    Value: !Ref GraphQLApiKey

  TodoTableName:
    Description: The name of the DynamoDB to-do table
    Value: !Ref TodoTable
